# Generated by asm2py
eax = ebx = ecx = edx = 0
zf = sf = False
stack = []
call_stack = []
pc = 0
while True:
    if pc == 0:
        eax = 7  # mov eax, 7
        call_stack.append(1)  # call square
        pc = 2
        continue
    if pc == 1:
        print(eax)  # print eax
        break  # hlt
    if pc == 2:  # square:
        eax *= eax  # mul eax, eax
        if call_stack:  # ret
            pc = call_stack.pop()
            continue
        break
    break  # no block matches pc: stop
